  {t="C", q=865, obj=1, name="Raptor Horns", gv="Collect", gw="Intact Raptor Horn", z=17, x=44.1, y=14.4, note="Collect Intact Raptor Horn", tip="On the way east to Echeyakee: Sunscale Scytheclaws prowl the plains east of the Dry Hills; any of them can drop an Intact Raptor Horn for Mebok in Ratchet.", section="The Barrens (14-21)", zoneName="The Barrens", p=577, place="Raptor Horns", was=1605}, -- 1752
