  {t="T", q=27, name="A Lesson to Learn", z=493, x=56.21, y=30.64, target={kind="npc", id=11802, name="Dendrite Starblaze"}, note="Dendrite Starblaze", tip="Dendrite Starblaze stands upstairs in his building in Nighthaven: go up inside, the arrow cannot tell the floors apart. The Shrine Baubles lie on the bed of Lake Elune'ara and fade within minutes: swim one straight to the Shrine of Remulos on the north-west shore, use it there and speak to Tajarri. Trial of the Lake runs on a timer: no teleport or Hearthstone until Tajarri has it.", races={"tauren", "skyborne"}, classes={"Druid"}, section="The Barrens (14-21)", zoneName="Moonglade", p=583, place="Trial of the Lake"}, -- 1769
  {t="T", q=6126, name="Lessons Anew", z=493, x=56.21, y=30.64, target={kind="npc", id=11802, name="Dendrite Starblaze"}, races={"tauren", "skyborne"}, classes={"Druid"}, section="The Barrens (14-21)", zoneName="Moonglade", p=583, place="Trial of the Lake"}, -- 1770
