  {t="T", q=1483, name="Ziz Fizziks", z=406, x=58.99, y=62.6, target={kind="npc", id=4201, name="Ziz Fizziks"}, note="Ziz Fizziks, inside", tip="The road climbs north as the Webwinder Path. Ziz Fizziks has a hut where the road forks east to Windshear Crag.", section="The Barrens (14-21)", zoneName="Stonetalon Mountains", p=682, place="Ziz Fizziks", was=1864}, -- 2012
  {t="A", q=1093, name="Super Reaper 6000", z=406, x=58.99, y=62.6, target={kind="npc", id=4201, name="Ziz Fizziks"}, section="The Barrens (14-21)", zoneName="Stonetalon Mountains", p=682, place="Ziz Fizziks", was=1865}, -- 2013
  {t="C", q=1093, name="Super Reaper 6000", gv="Collect", gw="Super Reaper 6000 Blueprints", z=406, x=62.51, y=53.84, note="Collect Super Reaper 6000 Blueprints", tip="East of Ziz, the Venture Company is clear-cutting Windshear Crag; one of the Operators carries the blueprints.", section="The Barrens (14-21)", zoneName="Stonetalon Mountains", p=683, place="Windshear Crag", was=1866}, -- 2014
