  {t="A", q=1090, name="Gerenzo's Orders", group=true, z=406, x=71.87, y=60, target={kind="npc", id=4276, name="Piznik"}, note="Piznik, below ground", tip="Piznik mines at the bottom of the Windshear Mine on the east side of the crag, past its kobolds (levels 19-23). Talk to him, then keep him alive for five minutes while he mines: a dozen or more kobolds come at him in waves, melee fighters first, then casters, and the mine's own kobolds respawn into the fight. If he dies, the quest fails.", section="The Barrens (14-21)", zoneName="Stonetalon Mountains", p=684, place="Piznik", was=1868}, -- 2016
  {t="C", q=1090, name="Gerenzo's Orders", group=true, z=406, x=71.87, y=60, section="The Barrens (14-21)", zoneName="Stonetalon Mountains", p=684, place="Piznik", was=1869}, -- 2017
