  {t="A", q=1092, name="Gerenzo's Orders", group=true, z=406, x=71.87, y=60, target={kind="npc", id=4276, name="Piznik"}, section="The Barrens (14-21)", zoneName="Stonetalon Mountains", p=684, place="Piznik", was=1871}, -- 2019
  {t="T", q=1092, name="Gerenzo's Orders", group=true, z=406, x=58.99, y=62.6, target={kind="npc", id=4201, name="Ziz Fizziks"}, note="Ziz Fizziks, inside", section="The Barrens (14-21)", zoneName="Stonetalon Mountains", p=685, place="Ziz Fizziks: Gerenzo's Orders", was=1872}, -- 2020
