  {t="A", q=6523, name="Protect Kaya", z=406, x=73.5, y=85.6, target={kind="npc", id=11856, name="Kaya Flathoof"}, note="Kaya Flathoof, inside Grundig's hut", tip="Careful: Three Grimtotems ambush her at the burned village and go for her, not you: pull them off her and kill their caster quickly.", section="The Barrens (14-21)", zoneName="Stonetalon Mountains", p=687, place="Kaya Flathoof"}, -- 2023
  {t="C", q=6523, name="Protect Kaya", z=406, x=77.1, y=90.8, section="The Barrens (14-21)", zoneName="Stonetalon Mountains", p=687, place="Kaya Flathoof"}, -- 2024
