  {t="G", text="Zeppelin to Undercity", z=14, x=50.8, y=13.5, section="Ashenvale & Silverpine Forest (21-23)", zoneName="Durotar", p=710, place="Zeppelin to Undercity"}, -- 2078
  {t="TR", text="Train at your class trainer", tip="Shari Stilwell trains Paladins in Brill, a short walk north up the road from the zeppelin towers. Come back down the same road for Silverpine.", classes={"Paladin"}, section="Ashenvale & Silverpine Forest (21-23)", p=711, place="Brill"}, -- 2079
  {t="N", text="Collect Half Pendant of Aquatic Endurance", note="Half Pendant of Aquatic Endurance, from the Strange Lockbox", tip="From the zeppelin towers, run south into Silverpine and west past the Dead Field to the coast: the Strange Lockbox lies at the bottom of very deep water there, beside an air fissure where you can breathe. Watch your breath on the way down. It holds the Half Pendant of Aquatic Endurance for Trial of the Sea Lion. Then on to the Sepulcher.", races={"tauren", "skyborne"}, classes={"Druid"}, onQuest={30}, section="Ashenvale & Silverpine Forest (21-23)", p=712, place="Strange Lockbox"}, -- 2080
  {t="A", q=493, name="Journey to Hillsbrad Foothills", z=130, x=42.8, y=40.86, target={kind="npc", id=1937, name="Apothecary Renferrel"}, note="Apothecary Renferrel: Lydon in Tarren Mill, next guide", tip="Down the road through Silverpine to the Sepulcher: from the zeppelin towers, south through Tirisfal; from the Strange Lockbox, south-east from the coast to the road. Shadow Priest Allister and Apothecary Renferrel stand by the crypt entrance.", section="Ashenvale & Silverpine Forest (21-23)", zoneName="Silverpine Forest", p=713, place="The Sepulcher", was=1932}, -- 2081
  {t="A", q=95981, name="Watching the Roads", foreverOnly=true, z=130, x=43.98, y=40.93, target={kind="npc", id=2121, name="Shadow Priest Allister"}, note="Shadow Priest Allister", section="Ashenvale & Silverpine Forest (21-23)", zoneName="Silverpine Forest", p=713, place="The Sepulcher", was=1933}, -- 2082
