  {t="T", q=6324, name="Return to Podrig", z=130, x=43.42, y=41.68, target={kind="npc", id=6389, name="Deathguard Podrig"}, note="Deathguard Podrig", tip="Deathguard Podrig stands just west of the crypt entrance: hand him Gordon's Crate from the Undercity.", races={"undead"}, onQuest={6324}, section="Ashenvale & Silverpine Forest (21-23)", zoneName="Silverpine Forest", p=714, place="Deathguard Podrig"}, -- 2084
