  {t="C", q=496, obj=2, name="Elixir of Suffering", gv="Collect", gw="Creeper Ichor", z=267, x=59, y=35.34, note="Collect Creeper Ichor", section="Hillsbrad Foothills (22-25)", zoneName="Hillsbrad Foothills", p=722, place="Bears, creepers and lions", was=1966}, -- 2117
