  {t="A", q=498, name="The Rescue", z=267, x=63.24, y=20.66, target={kind="npc", id=2229, name="Krusk"}, note="Krusk, inside", tip="Krusk wants his two scouts freed from Durnholde Keep before he trusts you with Infiltration.", notTurnedIn={498}, section="Hillsbrad Foothills & Arathi Highlands (29-33)", zoneName="Hillsbrad Foothills", p=898, place="Krusk"}, -- 2498
  {t="C", q=527, obj=1, name="Battle of Hillsbrad", gv="Kill", gw="Hillsbrad Farmer", z=267, x=35.13, y=37.43, note="Kill Hillsbrad Farmer", tip="West past the hills to the farms east of Hillsbrad town. Farmer Ray works the field by the northern farmhouse, Farmer Getz the one further south-east; Farmhands and Farmers are everywhere.", notTurnedIn={529}, section="Hillsbrad Foothills & Arathi Highlands (29-33)", zoneName="Hillsbrad Foothills", p=899, place="Hillsbrad Fields"}, -- 2499
  {t="C", q=527, obj=2, name="Battle of Hillsbrad", gv="Kill", gw="Hillsbrad Farmhand", z=267, x=35.16, y=37.7, note="Kill Hillsbrad Farmhand", notTurnedIn={529}, section="Hillsbrad Foothills & Arathi Highlands (29-33)", zoneName="Hillsbrad Foothills", p=899, place="Hillsbrad Fields"}, -- 2500
