  {t="C", q=552, name="Helcular's Revenge", gv="Collect", gw="Helcular's Rod", z=267, x=44.5, y=29.4, note="Collect Helcular's Rod", tip="South-west, the Cave and Ferocious Yetis (30-32) fill the Foothill Caverns in the hills west of Tarren Mill; about one in sixteen carries the rod. Stay in these caverns: the Mountain and Giant Yetis (32-34) of the cave further north carry it too, but at 29-30 they hit hard and come in pairs.", section="Hillsbrad Foothills & Arathi Highlands (29-33)", zoneName="Hillsbrad Foothills", p=908, place="Helcular's Rod", was=2307}, -- 2522
  {t="G", text="Foothill Caverns", z=267, x=44.0, y=28.0, tip="Tarren Mill's Prison Break In, Stone Tokens and The Hammer May Fall are offered from level 30. Below it? Keep killing the yetis in these caves until level 30. Or, with a group, run the Scarlet Monastery dungeon (Graveyard) or the Blackfathom Deeps dungeon instead.", lvlBelow=30.0, section="Hillsbrad Foothills & Arathi Highlands (29-33)", zoneName="Hillsbrad Foothills", p=909, place="Level 30"}, -- 2523
  {t="N", text="Reach level 30", note="grind on Cave Yeti", lvlBelow=30.0, section="Hillsbrad Foothills & Arathi Highlands (29-33)", p=909, place="Level 30"}, -- 2524
  {t="C", q=532, obj=2, name="Battle of Hillsbrad", gv="Kill", gw="Hillsbrad Councilman", z=267, x=29.59, y=39.72, note="Kill Hillsbrad Councilman", tip="On to Hillsbrad town, south-west of the yeti caves. The town hall is on the town's west side: Magistrate Burnside (30) and Clerk Horrace Whitesteed are inside with the Town Registry; the Proclamation is pinned up beside it. Councilmen walk the town.", section="Hillsbrad Foothills & Arathi Highlands (29-33)", zoneName="Hillsbrad Foothills", p=910, place="Town hall", was=2310}, -- 2525
  {t="C", q=532, obj=3, name="Battle of Hillsbrad", z=267, x=29.73, y=41.75, note="Hillsbrad Proclamation, inside", section="Hillsbrad Foothills & Arathi Highlands (29-33)", zoneName="Hillsbrad Foothills", p=910, place="Town hall", was=2311}, -- 2526
