  {t="A", q=556, name="Stone Tokens", z=267, x=61.5, y=20.93, target={kind="npc", id=2437, name="Keeper Bel'varil"}, note="Keeper Bel'varil, inside: offered from level 30", section="Hillsbrad Foothills & Arathi Highlands (29-33)", zoneName="Hillsbrad Foothills", p=911, place="Tarren Mill", was=2321}, -- 2536
  {t="A", q=676, name="The Hammer May Fall", z=267, x=61.87, y=19.57, target={kind="npc", id=2770, name="Tallow"}, note="Tallow: for Drum Fel in Hammerfall, later in this guide (from level 30)", section="Hillsbrad Foothills & Arathi Highlands (29-33)", zoneName="Hillsbrad Foothills", p=911, place="Tarren Mill", was=2322}, -- 2537
  {t="C", q=553, obj=1, name="Helcular's Revenge", z=267, x=43.9, y=28.1, note="Flame of Azel", tip="Back into the yeti caves west of Tarren Mill with the Rod of Helcular. The path splits just inside: the Flame of Azel burns on the upper level to the right, the Flame of Veraz on the lower level to the left, past more yetis.", section="Hillsbrad Foothills & Arathi Highlands (29-33)", zoneName="Hillsbrad Foothills", p=912, place="Foothill Caverns", was=2323}, -- 2538
  {t="C", q=553, obj=2, name="Helcular's Revenge", z=267, x=44.1, y=26.6, note="Flame of Veraz", section="Hillsbrad Foothills & Arathi Highlands (29-33)", zoneName="Hillsbrad Foothills", p=912, place="Foothill Caverns", was=2324}, -- 2539
  {t="C", q=553, obj=3, name="Helcular's Revenge", z=267, x=41.7, y=6.4, note="Flame of Uzel", tip="Careful: Giant and Mountain Yetis (32-34) stand around the flame, often in pairs, and Frostmaw, a rare yeti (37), roams nearby. At 30-31 they are over your level: pull the yetis one at a time from the cave mouth before you use the Rod, and watch for Frostmaw before you go in.", section="Hillsbrad Foothills & Arathi Highlands (29-33)", zoneName="Hillsbrad Foothills", p=913, place="Flame of Uzel", was=2325}, -- 2540
  {t="G", text="The Dalaran crater's eastern rim", z=36, x=24.5, y=82.8, section="Hillsbrad Foothills & Arathi Highlands (29-33)", zoneName="Alterac Mountains", p=914, place="Alterac Mountains"}, -- 2541
  {t="C", q=544, obj=1, name="Prison Break In", z=36, x=19.91, y=85.97, note="Dermot", tip="Head west along the foot of the mountains to the violet dome of Dalaran. Ricter, Alina and Dermot (33-34) stand together inside the crater's eastern rim, Kegan Darkmar (35) a little west of them; each carries one Bloodstone piece. The Shield Guards and Theurgists (31-33) around them drop the Worn Stone Tokens. Careful: Many guards stand in linked pairs and others patrol alone around the camp.", section="Hillsbrad Foothills & Arathi Highlands (29-33)", zoneName="Alterac Mountains", p=915, place="The Dalaran crater", was=2327}, -- 2542
  {t="C", q=544, obj=2, name="Prison Break In", z=36, x=20.16, y=84.28, note="Ricter", section="Hillsbrad Foothills & Arathi Highlands (29-33)", zoneName="Alterac Mountains", p=915, place="The Dalaran crater", was=2328}, -- 2543
