  {t="C", q=93680, obj=1, name="Key to the City", foreverOnly=true, z=36, x=16.4, y=89.3, note="Grimy Key: an object to loot, by the traitors", section="Hillsbrad Foothills & Arathi Highlands (29-33)", zoneName="Alterac Mountains", p=915, place="The Dalaran crater"}, -- 2546
  {t="C", q=556, name="Stone Tokens", gv="Collect", gw="Worn Stone Token", z=36, x=18.42, y=87.99, note="Collect Worn Stone Token", section="Hillsbrad Foothills & Arathi Highlands (29-33)", zoneName="Alterac Mountains", p=915, place="The Dalaran crater", was=2331}, -- 2547
  {t="G", text="Azurelode Mine", z=267, x=28.5, y=55.0, section="Hillsbrad Foothills & Arathi Highlands (29-33)", zoneName="Hillsbrad Foothills", p=916, place="Hillsbrad Foothills"}, -- 2548
  {t="C", q=539, obj=2, name="Battle of Hillsbrad", gv="Kill", gw="Hillsbrad Miner", z=267, x=28.3, y=54.8, note="Kill Hillsbrad Miner", tip="Head south past Hillsbrad town to the Azurelode Mine. Miners work the tunnels; Foreman Bonds (30) and Miner Hackett (29) are deep inside.", section="Hillsbrad Foothills & Arathi Highlands (29-33)", zoneName="Hillsbrad Foothills", p=917, place="Azurelode Mine", was=2333}, -- 2549
  {t="C", q=567, obj=3, name="Dangerous!", gv="Kill", gw="Miner Hackett", z=267, x=31.8, y=52.7, note="Kill Miner Hackett", section="Hillsbrad Foothills & Arathi Highlands (29-33)", zoneName="Hillsbrad Foothills", p=917, place="Azurelode Mine", was=2334}, -- 2550
  {t="C", q=539, obj=1, name="Battle of Hillsbrad", z=267, x=31.21, y=56.01, note="Inside Azurelode Mine", section="Hillsbrad Foothills & Arathi Highlands (29-33)", zoneName="Hillsbrad Foothills", p=917, place="Azurelode Mine", was=2335}, -- 2551
  {t="G", text="Torn Fin beach", z=267, x=36.0, y=68.0, tip="The Torn Fin murlocs camp on the beaches south-west of Southshore's bay, below the mine.", onQuest={515}, section="Hillsbrad Foothills & Arathi Highlands (29-33)", zoneName="Hillsbrad Foothills", p=918, place="Torn Fin murlocs"}, -- 2552
  {t="C", q=515, obj=3, name="Elixir of Agony", gv="Collect", gw="Torn Fin Eye", optional=true, z=267, x=36.06, y=68.74, note="Collect Torn Fin Eye", onQuest={515}, section="Hillsbrad Foothills & Arathi Highlands (29-33)", zoneName="Hillsbrad Foothills", p=918, place="Torn Fin murlocs", was=2337}, -- 2553
  {t="G", text="North of Southshore's graveyard", z=267, x=53.4, y=48.8, tip="Head east to Southshore's graveyard, on the north-east edge of the town: Helcular's grave lies among the others. Come at it from the north, down the slope above the town. Southshore Guards (55) stand at the graveyard's north-west corner and south-east of the grave: walk in between them, hand the quest in and leave the way you came.", section="Hillsbrad Foothills & Arathi Highlands (29-33)", zoneName="Hillsbrad Foothills", p=919, place="Helcular's Grave"}, -- 2554
  {t="T", q=553, name="Helcular's Revenge", z=267, x=52.8, y=53.4, target={kind="object", id=1767, name="Helcular's Grave"}, note="Helcular's Grave", section="Hillsbrad Foothills & Arathi Highlands (29-33)", zoneName="Hillsbrad Foothills", p=919, place="Helcular's Grave", was=2338}, -- 2555
  {t="G", text="Daggerspine shore", z=267, x=53.0, y=65.0, tip="The Daggerspine naga line the shore south-east of the town.", onQuest={515}, section="Hillsbrad Foothills & Arathi Highlands (29-33)", zoneName="Hillsbrad Foothills", p=920, place="Daggerspine naga"}, -- 2556
