  {t="A", q=535, name="Valik", z=36, x=57.17, y=69.51, target={kind="npc", id=2333, name="Henchman Valik"}, tip="From Southshore head north past Tarren Mill and follow the road on into the Alterac foothills. Valik waits by the Syndicate camp. He offers his errand only while you carry Krusk's Infiltration: hand him the stout at once, and his reward is the Syndicate Missive Krusk wants. A missive from the Syndicate here does the same: with one in your bags the guide passes Valik.", notReady=533, onQuest={533}, section="Hillsbrad Foothills & Arathi Highlands (29-33)", zoneName="Alterac Mountains", p=921, place="Henchman Valik", was=2303}, -- 2558
  {t="T", q=535, name="Valik", z=36, x=57.17, y=69.51, target={kind="npc", id=2333, name="Henchman Valik"}, notReady=533, onQuest={533}, section="Hillsbrad Foothills & Arathi Highlands (29-33)", zoneName="Alterac Mountains", p=921, place="Henchman Valik", was=2305}, -- 2559
  {t="C", q=533, name="Infiltration", gv="Collect", gw="Syndicate Missive", z=36, x=57.6, y=68.54, note="Collect Syndicate Missive", tip="Only if Valik's missive didn't come your way: the Syndicate Footpads and Thieves (32-34) around the camps west of the road carry missives too; about one in three drops one. Careful: at 31-32 they are still above you and stand close together, with Wizards (34-35) among them: pull one at a time from the camp's edge.", section="Hillsbrad Foothills & Arathi Highlands (29-33)", zoneName="Alterac Mountains", p=922, place="Syndicate missives", was=2304}, -- 2560
  {t="T", q=533, name="Infiltration", z=267, x=63.24, y=20.66, target={kind="npc", id=2229, name="Krusk"}, note="Krusk, inside", tip="Head back south down the road to Tarren Mill.", section="Hillsbrad Foothills & Arathi Highlands (29-33)", zoneName="Hillsbrad Foothills", p=923, place="Tarren Mill", was=2317}, -- 2561
