  {t="C", q=676, obj=2, name="The Hammer May Fall", z=45, x=32.82, y=43.14, note="Below ground", section="Hillsbrad Foothills & Arathi Highlands (29-33)", zoneName="Arathi Highlands", p=933, place="Boulderfist camp", was=2366}, -- 2588
  {t="G", text="Boulderfist camp", z=45, x=31.2, y=48.0, tip="Hammerfall's quests are 32-36. Below 31? Keep killing the Boulderfist Ogres and Enforcers at this camp until level 31. Or, with a group, run the Scarlet Monastery dungeon (Graveyard) or the Blackfathom Deeps dungeon instead.", lvlBelow=31.0, section="Hillsbrad Foothills & Arathi Highlands (29-33)", zoneName="Arathi Highlands", p=934, place="Level 31"}, -- 2589
