  {t="N", text="Kodo Kombobulator", z=405, x=51.0, y=58.5, note="on an Aged, Dying or Ancient Kodo in the graveyard; don't kill it", tip="Use Smeed's Kodo Kombobulator on an Aged, Dying or Ancient Kodo in the graveyard and walk the tamed kodo back to Smeed. At his camp, talk to the kodo: that counts it and lets you tame the next. Five kodos, one at a time.", section="Thousand Needles & Desolace (32-34)", zoneName="Desolace", p=967, place="Kodo Graveyard"}, -- 2682
  {t="C", q=5561, obj=1, name="Kodo Roundup", z=405, x=60.6, y=61.6, note="the tamed kodo, at Smeed's camp: talk to it, five times", section="Thousand Needles & Desolace (32-34)", zoneName="Desolace", p=967, place="Kodo Graveyard"}, -- 2683
  {t="T", q=5561, name="Kodo Roundup", z=405, x=60.86, y=61.86, target={kind="npc", id=11596, name="Smeed Scrabblescrew"}, note="Smeed Scrabblescrew", section="Thousand Needles & Desolace (32-34)", zoneName="Desolace", p=968, place="Scrabblescrew's Camp", was=2462}, -- 2684
  {t="G", text="Scorpashi Lashers", z=405, x=59.9, y=54.6, tip="Shadowprey's Hand of Iruxos and the coast's naga want 33. Below that? The Scorpashi Lashers on the slopes north of Smeed's camp are on your way west: kill them until level 33. Or, with a group, run the Scarlet Monastery dungeon (Library) instead.", lvlBelow=33.0, section="Thousand Needles & Desolace (32-34)", zoneName="Desolace", p=969, place="Level 33"}, -- 2685
  {t="N", text="Reach level 33", note="grind on Scorpashi Lasher", lvlBelow=33.0, section="Thousand Needles & Desolace (32-34)", p=969, place="Level 33"}, -- 2686
  {t="A", q=97265, name="Hate the Hatefury", optional=true, foreverOnly=true, z=405, x=25.32, y=67.05, target={kind="npc", id=268705, name="Aka'rai"}, note="Aka'rai: the Hatefury satyrs of Sargeron, later in this guide", tip="Aka'rai may not be here on Forever: if Aka'rai doesn't offer Hate the Hatefury, skip it.", section="Thousand Needles & Desolace (32-34)", zoneName="Desolace", p=970, place="Shadowprey Village", was=2465}, -- 2687
