  {t="FP", text="Shadowprey Village flight path", note="Thalon, at the village's south-west end", section="Thousand Needles & Desolace (32-34)", p=970, place="Shadowprey Village"}, -- 2693
  {t="A", q=5741, name="Sceptre of Light", z=405, x=38.88, y=27.16, target={kind="npc", id=11863, name="Azore Aldamort"}, note="Azore Aldamort", tip="Head north along the coast, then inland to the ruined tower of Ethel Rethor: Azore Aldamort waits inside. The coast's clams and naga come after Thunder Axe Fortress, on one walk north to Ranazjar Isle.", section="Thousand Needles & Desolace (32-34)", zoneName="Desolace", p=971, place="Ethel Rethor", was=2476}, -- 2694
  {t="C", q=1435, name="The Burning of Spirits", gv="Collect", gw="Infused Burning Gem", z=405, x=55.0, y=26.5, note="Collect Infused Burning Gem", tip="Head east to Thunder Axe Fortress. Beat a Burning Blade cultist down, then use the Burning Gem on it before it dies to fill one Infused Burning Gem. The Burning Blade Seer stands on the fortress's top floor with the Sceptre. The cultists also drop a Flayed Demon Skin now and then (1-5%); if one drops, read it. Hand of Iruxos: clear the middle of the largest building, then use the Demon Pick on the red Hand of Iruxos Crystal there. A Demon Spirit (37) comes out: kill it for the Demon Box.", section="Thousand Needles & Desolace (32-34)", zoneName="Desolace", p=972, place="Thunder Axe Fortress", was=2477}, -- 2695
  {t="C", q=5741, name="Sceptre of Light", z=405, x=55.2, y=30.1, note="On the top floor", section="Thousand Needles & Desolace (32-34)", zoneName="Desolace", p=972, place="Thunder Axe Fortress", was=2478}, -- 2696
