  {t="A", q=570, name="Mok'thardin's Enchantment", z=33, x=32.12, y=29.24, target={kind="npc", id=2465, name="Far Seer Mok'thardin"}, note="Far Seer Mok'thardin: the Shadowmaw claws and the tigress fang come at the end of this guide", section="Stranglethorn Vale (34-36)", zoneName="Stranglethorn Vale", p=1004, place="Grom'gol", was=2587}, -- 2817
  {t="G", text="Lashtail Raptors", z=33, x=32.4, y=24.6, tip="Booty Bay's and Grom'gol's next quests are 35-38. Still below 35 after Aggro'gosh's hand-in? The Lashtail Raptors (35) hunt the jungle just north of Grom'gol: kill them until level 35. Or, with a group, run the Scarlet Monastery dungeon (Library or Armory) instead.", lvlBelow=35.0, section="Stranglethorn Vale (34-36)", zoneName="Stranglethorn Vale", p=1005, place="Level 35"}, -- 2818
  {t="N", text="Reach level 35", note="grind on Lashtail Raptor", lvlBelow=35.0, section="Stranglethorn Vale (34-36)", p=1005, place="Level 35"}, -- 2819
