  {t="C", q=629, name="The Vile Reef", z=33, x=24.8, y=22.9, note="Underwater", tip="North-west of Grom'gol the Vile Reef lies under the water off the coast. The Tablet Shard rests on the sea floor by the sunken ruins; watch your breath and the murlocs.", section="Stranglethorn Vale (34-36)", zoneName="Stranglethorn Vale", p=1009, place="The Vile Reef", was=2590}, -- 2832
  {t="C", q=596, name="Bloody Bone Necklaces", gv="Collect", gw="Bloody Bone Necklace", z=33, x=28.81, y=19.95, note="Collect Bloody Bone Necklace", tip="The Bloodscalp trolls hold the ruins up the coast north of the reef and the village beyond; every one can drop a Bloody Bone Necklace. Keep looting pages of The Green Hills of Stranglethorn.", section="Stranglethorn Vale (34-36)", zoneName="Stranglethorn Vale", p=1010, place="Ruins of Zul'Kunda: kill these as you meet them", was=2591}, -- 2833
