  {t="C", q=570, obj=1, name="Mok'thardin's Enchantment", gv="Collect", gw="Shadowmaw Claw", z=33, x=36.03, y=33.95, note="Collect Shadowmaw Claw", tip="East of the Mosh'Ogg hills, Shadowmaw Panthers (37-38) stalk the jungle towards the lake; the Stranglethorn Tigresses roam the same ground and now and then drop a pristine fang. Snapjaw Crocolisks line the river just west of the jungle; keep their skins for Drizzlik. Careful: Shadowmaw Panthers (level 37-38) and Elder Shadowmaw Panthers (level 42-43) use Sneak while out of combat, so they remain hidden until you get near them.", section="Stranglethorn Vale (34-36)", zoneName="Stranglethorn Vale", p=1012, place="Stranglethorn Vale: kill these as you meet them", was=2599}, -- 2839
  {t="C", q=570, obj=2, name="Mok'thardin's Enchantment", gv="Collect", gw="Pristine Tigress Fang", z=33, x=36.03, y=33.95, note="Collect Pristine Tigress Fang", section="Stranglethorn Vale (34-36)", zoneName="Stranglethorn Vale", p=1012, place="Stranglethorn Vale: kill these as you meet them", was=2600}, -- 2840
  {t="C", q=192, name="Panther Mastery", gv="Kill", gw="Shadowmaw Panther", z=33, x=41.3, y=34.8, note="Kill Shadowmaw Panther", section="Stranglethorn Vale (34-36)", zoneName="Stranglethorn Vale", p=1012, place="Stranglethorn Vale: kill these as you meet them", was=2618}, -- 2841
  {t="C", q=577, name="Some Assembly Required", gv="Collect", gw="Snapjaw Crocolisk Skin", z=33, x=39.9, y=28.4, note="Collect Snapjaw Crocolisk Skin", section="Stranglethorn Vale (34-36)", zoneName="Stranglethorn Vale", p=1012, place="Stranglethorn Vale: kill these as you meet them", was=2601}, -- 2842
  {t="C", q=339, obj=1, name="Chapter I", gv="Collect", gw="Green Hills of Stranglethorn - Page 1", optional=true, z=33, x=42.45, y=33.27, note="Collect Green Hills of Stranglethorn - Page 1", tip="Pages of The Green Hills of Stranglethorn drop at about 1% each from the Bloodscalp and Skullsplitter trolls; keep every page you loot and look on the auction house for the rest. Barnil takes the chapters on your next Stranglethorn visit, at about 40.", section="Stranglethorn Vale (34-36)", zoneName="Stranglethorn Vale", p=1013, place="Green Hills pages", was=2603}, -- 2843
