  {t="T", q=1718, name="The Islander", z=17, x=68.62, y=49.16, target={kind="npc", id=6236, name="Klannoc Macleod"}, note="Klannoc Macleod", tip="Head south along the coast from Ratchet to Fray Island. Klannoc Macleod stands by the arena: step on the grate to start the fight; the challengers come one at a time, then Big Will (33).", classes={"Warrior"}, section="Dustwallow Marsh & Desolace (36-38)", zoneName="The Barrens", p=1039, place="The Affray", was=2690}, -- 2925
