  {t="A", q=5581, name="Portals of the Legion", z=405, x=25.82, y=68.21, target={kind="npc", id=11624, name="Taiga Wisemane"}, note="Taiga Wisemane", tip="Taiga Wisemane stands in the village.", section="Dustwallow Marsh & Desolace (36-38)", zoneName="Desolace", p=1041, place="Shadowprey Village", was=2696}, -- 2931
  {t="G", text="Mannoroc Coven", z=405, x=52.0, y=78.0, tip="Head east to Mannoroc Coven. With the Hand of Iruxos from Taiga in your bags, open a demon portal's ring: a Demon Portal Guardian (38-39) comes out; kill it to close that portal. Six portals. Careful: Infernals, Doomguards and Burning Blade Summoners walk close by many portals and may join in; kill nearby mobs first or drag the guardian away, for example toward the coven's central lake.", section="Dustwallow Marsh & Desolace (36-38)", zoneName="Desolace", p=1042, place="Portals of the Legion"}, -- 2932
  {t="C", q=5581, name="Portals of the Legion", z=405, x=52.6, y=77.4, section="Dustwallow Marsh & Desolace (36-38)", zoneName="Desolace", p=1042, place="Portals of the Legion", was=2698}, -- 2933
