  {t="C", q=93225, obj=1, name="Carved Centaur Totems", gv="Collect", gw="5 Carved Centaur Totem", foreverOnly=true, z=405, x=66.52, y=69.07, note="Collect 5 Carved Centaur Totem", tip="West of the post, the Maraudine centaurs hold the Valley of Spears. Every Maraudine can drop a Carved Centaur Totem and an ear for Felgur's Centaur Bounty.", section="Dustwallow Marsh & Desolace (36-38)", zoneName="Desolace", p=1044, place="Valley of Spears", was=2700}, -- 2935
  {t="C", q=1366, name="Centaur Bounty", gv="Collect", gw="Centaur Ear", z=405, x=66.52, y=69.07, note="Collect Centaur Ear", section="Dustwallow Marsh & Desolace (36-38)", zoneName="Desolace", p=1044, place="Valley of Spears", was=2701}, -- 2936
  {t="A", q=6132, name="Get Me Out of Here!", z=405, x=33.95, y=53.5, target={kind="npc", id=12277, name="Melizza Brimbuzzle"}, tip="Careful: The scripted groups are linked and only appear during the escort, so you cannot clear them in advance or pull them one at a time. Clearing the normal centaurs on the path before you start does help.", section="Dustwallow Marsh & Desolace (36-38)", zoneName="Desolace", p=1045, place="Melizza Brimbuzzle", was=2702}, -- 2937
  {t="C", q=6132, name="Get Me Out of Here!", z=405, x=33.95, y=53.5, section="Dustwallow Marsh & Desolace (36-38)", zoneName="Desolace", p=1045, place="Melizza Brimbuzzle", was=2703}, -- 2938
