  {t="T", q=507, name="Lord Aliden Perenolde", z=36, x=39.3, y=14.31, target={kind="npc", id=2317, name="Elysa"}, note="Elysa", section="Alterac Mountains & Arathi Highlands (38-39)", zoneName="Alterac Mountains", p=1067, place="Lord Aliden Perenolde", was=2737}, -- 2975
