  {t="C", q=651, name="Stones of Binding", z=45, x=66.7, y=29.72, note="Cresting Key", tip="Careful: Each center stone is guarded by around three elementals near level 39 that attack together if you click the stone without clearing them: Burning Exiles at West, Thundering Exiles at Outer, Cresting Exiles at East.", section="Alterac Mountains & Arathi Highlands (38-39)", zoneName="Arathi Highlands", p=1079, place="The Stone of East Binding", was=2761}, -- 3000
  {t="C", q=678, obj=1, name="Call to Arms", gv="Kill", gw="Boulderfist Brute", z=45, x=52.26, y=71.48, note="Kill Boulderfist Brute", tip="The Boulderfist Brutes camp outside the ogres' hall, far south-west of Hammerfall; the Magus stand among them. Pull them one at a time.", section="Alterac Mountains & Arathi Highlands (38-39)", zoneName="Arathi Highlands", p=1080, place="Boulderfist Hall", was=2762}, -- 3001
