  {t="FP", text="Kargath flight path", tip="Kargath is the Horde fortress built into the cliffs at the zone's western edge. Neeka Bloodscar stands on Kargath's upper level, high above the flight master: take the ramps up, the arrow cannot tell the levels apart.", section="Badlands (39-40)", p=1098, place="Kargath"}, -- 3056
  {t="SH", text="Kargath", z=3, x=2.82, y=45.86, note="Innkeeper Shul'kar", section="Badlands (39-40)", zoneName="Badlands", p=1098, place="Kargath"}, -- 3057
