  {t="A", q=3161, name="Gahz'ridian", z=440, x=52.71, y=45.92, target={kind="npc", id=7771, name="Marvon Rivetseeker"}, tip="West along the road south; Marvon camps by the ruins at the Broken Pillar. Put on his Gahz'ridian Detector: it shows the buried ornaments, here and around the Dunemaul Compound.", section="Tanaris & Searing Gorge (46-48)", zoneName="Tanaris", p=1259, place="Marvon Rivetseeker", was=3250}, -- 3518
  {t="C", q=3161, obj=1, name="Gahz'ridian", gv="Collect", gw="Gahz'ridian Ornament", z=440, x=52.3, y=45.3, note="Collect Gahz'ridian Ornament", tip="South of the Noxious Lair the Dunemaul ogres hold their compound, with Gor'marok the Ravager at its eastern end. Dig up Gahz'ridian ornaments between the fights.", section="Tanaris & Searing Gorge (46-48)", zoneName="Tanaris", p=1260, place="Broken Pillar: kill these as you meet them", was=3251}, -- 3519
  {t="C", q=5863, obj=1, name="The Dunemaul Compound", gv="Kill", gw="Dunemaul Brute", z=440, x=42.68, y=53.15, note="Kill Dunemaul Brute", section="Tanaris & Searing Gorge (46-48)", zoneName="Tanaris", p=1260, place="Broken Pillar: kill these as you meet them", was=3252}, -- 3520
