  {t="A", q=1560, name="Tooga's Quest", z=440, x=30, y=65, target={kind="npc", id=5955, name="Tooga"}, note="Tooga", tip="Tooga waits in the valley. Walk him all the way to his wife Torta in Steamwheedle Port, north-east across the desert: stay close, slow down for him and fight off what attacks him. Do not mount or hearth out of his reach. Yeh'kinya stands in the port too.", section="Tanaris & Searing Gorge (46-48)", zoneName="Tanaris", p=1263, place="Tooga's escort", was=3260}, -- 3528
  {t="C", q=1560, name="Tooga's Quest", z=440, x=66.58, y=25.67, section="Tanaris & Searing Gorge (46-48)", zoneName="Tanaris", p=1263, place="Tooga's escort", was=3261}, -- 3529
