  {t="A", q=5901, name="A Plague Upon Thee", z=85, x=83.29, y=72.34, target={kind="npc", id=11615, name="Mickey Levine"}, note="Mickey Levine", tip="Leave the Undercity and ride east along the road through Tirisfal Glades to the Bulwark, the Forsaken fort on the border.", section="Un'Goro Crater, Burning Steppes & Western Plaguelands (51-53)", zoneName="Tirisfal Glades", p=1444, place="The Bulwark", was=3698}, -- 3993
