  {t="A", q=5542, name="Demon Dogs", z=139, x=5.16, y=35.57, target={kind="npc", id=1855, name="Tirion Fordring"}, tip="Ride north along the eastern hills; Tirion lives in a small house by the Thondroril River, at the border with the Eastern Plaguelands.", section="Felwood & Western Plaguelands (53-55)", zoneName="Eastern Plaguelands", p=1448, place="Tirion Fordring", was=3755}, -- 4006
