  {t="N", text="Tirion's hunts are in the Eastern Plaguelands: keep them for later.", section="Felwood & Western Plaguelands (53-55)", p=1448, place="Tirion Fordring"}, -- 4009
  {t="A", q=6164, name="Augustus' Receipt Book", z=139, x=11.36, y=26.37, target={kind="npc", id=12384, name="Augustus the Touched"}, note="Inside", tip="Cross the river east into Terrordale, the ruined town in the north-west of the Eastern Plaguelands. Augustus sits in a hut at its edge.", section="Felwood & Western Plaguelands (53-55)", zoneName="Eastern Plaguelands", p=1449, place="Augustus the Touched", was=3714}, -- 4010
  {t="C", q=6164, name="Augustus' Receipt Book", z=139, x=14.01, y=24.22, note="Upstairs", tip="The Large Termite Mounds stand all over the hills east of Terrordale. Use the Empty Termite Jar on each mound you pass.", section="Felwood & Western Plaguelands (53-55)", zoneName="Eastern Plaguelands", p=1450, place="Terrordale: kill these as you meet them", was=3715}, -- 4011
  {t="C", q=5901, name="A Plague Upon Thee", gv="Collect", gw="Plagueland Termites", z=139, x=15.91, y=26.75, note="Collect Plagueland Termites", section="Felwood & Western Plaguelands (53-55)", zoneName="Eastern Plaguelands", p=1450, place="Terrordale: kill these as you meet them", was=3716}, -- 4012
